//
// Decodes every file generated by tools/test-media/make_exr.py and checks known
// pixel values. Regenerate media with:
//   uv run --python 3.12 --with OpenEXR --with numpy python tools/test-media/make_exr.py

import { beforeAll, describe, expect, test } from 'vitest';
import {
  createExrDecoder,
  ExrError,
  ExrUnsupportedError,
  groupLayers,
  halfToFloat,
  type DecodedExr,
  type ExrDecoder,
} from '../src/index.ts';
import {
  check,
  haveMedia,
  haveWasm,
  loadManifest,
  readMedia,
  type ManifestFile,
  type Sample,
} from './helpers.ts';

const ready = haveMedia && haveWasm;
if (!ready)
  console.warn(
    `[exr-wasm] skipping decode tests: ${!haveWasm ? 'dist-wasm/openexr.wasm missing (run scripts/build-wasm.sh)' : ''} ${
      !haveMedia ? 'test media missing (run tools/test-media/make_exr.py)' : ''
    }`,
  );

function pixel(d: DecodedExr, x: number, y: number): number[] {
  const i = (y * d.width + x) * 4;
  const p = d.pixels;
  const out: number[] = [];
  for (let c = 0; c < 4; c++) out.push(d.format === 'half' ? halfToFloat(p[i + c]) : p[i + c]);
  return out;
}

function checkSamples(
  d: DecodedExr,
  samples: Sample[],
  tolRel: number,
  tolAbs: number,
  label: string,
) {
  const errors: string[] = [];
  for (const s of samples) {
    const px = pixel(d, s.x, s.y);
    s.rgba.forEach((e, c) => {
      const err = check(px[c], e, tolRel, tolAbs, d.format === 'half');
      if (err)
        errors.push(
          `${label} part ${s.part} layer '${s.layer}' (${s.x},${s.y}) ${'RGBA'[c]}: ${err}`,
        );
    });
  }
  expect(errors).toEqual([]);
}

function groupBy<T>(xs: T[], key: (x: T) => string): Map<string, T[]> {
  const m = new Map<string, T[]>();
  for (const x of xs) {
    const k = key(x);
    m.set(k, [...(m.get(k) ?? []), x]);
  }
  return m;
}

describe.skipIf(!ready)('exr-wasm decode', () => {
  let dec: ExrDecoder;
  const manifest = ready ? loadManifest() : { files: [] as ManifestFile[] };
  const files = manifest.files.filter((f) => f.kind !== 'deep' && f.kind !== 'bench');

  beforeAll(async () => {
    dec = await createExrDecoder();
  });

  describe.each(files.map((f) => [f.path, f] as const))('%s', (_path, f) => {
    test('header', () => {
      const info = dec.readInfo(readMedia(f.path));
      const p0 = info.parts[0];
      if (f.parts) {
        expect(info.parts.map((p) => p.name)).toEqual(f.parts.map((p) => p.name));
        f.parts.forEach((ep, i) => {
          const p = info.parts[i];
          expect(p.type).toBe(ep.type);
          expect(p.compression).toBe(ep.compression);
          expect([p.width, p.height]).toEqual([ep.width, ep.height]);
          if (ep.dataWindow) expect(p.dataWindow).toEqual(ep.dataWindow);
        });
        return;
      }
      expect(info.parts.length).toBe(1);
      expect([p0.width, p0.height]).toEqual([f.width, f.height]);
      if (f.compression) expect(p0.compression).toBe(f.compression);
      if (f.dataWindow) expect(p0.dataWindow).toEqual(f.dataWindow);
      if (f.displayWindow) expect(p0.displayWindow).toEqual(f.displayWindow);
      if (f.chromaticities) {
        const c = p0.chromaticities!;
        const flat = [...c.red, ...c.green, ...c.blue, ...c.white];
        flat.forEach((v, i) => expect(v).toBeCloseTo(f.chromaticities![i], 6));
        expect(p0.attributes.owner).toMatch(/scenegrade/);
      }
      if (f.kind === 'tiled') expect(p0.tiles?.xSize).toBe((f as { tileSize?: number }).tileSize);
      if (f.expectedLayers) {
        const got = Object.fromEntries(p0.layers.map((l) => [l.name, l.mapping]));
        expect(got).toEqual(f.expectedLayers);
        expect(p0.layers[0].name).toBe('');
      }
    });

    const byTarget = groupBy(f.samples, (s) => `${s.part}|${s.layer}`);
    test.each([...byTarget.keys()])('pixels %s (half)', (key) => {
      const samples = byTarget.get(key)!;
      const { part, layer } = samples[0];
      const d = dec.decode(readMedia(f.path), { part, layer });
      expect(d.format).toBe('half');
      expect(d.pixels).toBeInstanceOf(Uint16Array);
      expect(d.pixels.length).toBe(d.width * d.height * 4);
      expect(d.failedChunks).toBe(0);
      expect(d.layer).toBe(layer);
      checkSamples(d, samples, f.tolRel ?? 0, f.tolAbs ?? 0, f.path);
    });

    test('pixels (float32 output)', () => {
      const samples = byTarget.get([...byTarget.keys()][0]) ?? [];
      if (!samples.length) return;
      const { part, layer } = samples[0];
      const d = dec.decode(readMedia(f.path), { part, layer, format: 'float' });
      expect(d.pixels).toBeInstanceOf(Float32Array);
      // float files are exact in float output; half files are exact either way
      const exact = f.lossless && (f.pixelType === 'float' || f.kind === 'chart-float');
      checkSamples(d, samples, exact ? 0 : (f.tolRel ?? 0), exact ? 0 : (f.tolAbs ?? 0), f.path);
    });
  });

  test('lossless compressions decode bit-identical to NONE', () => {
    const groups = groupBy(
      files.filter((f) => f.referenceGroup),
      (f) => f.referenceGroup!,
    );
    expect(groups.get('chart_half')!.length).toBeGreaterThanOrEqual(8);
    for (const [, group] of groups) {
      const ref = dec.decode(readMedia(group[0].path));
      for (const f of group.slice(1)) {
        const d = dec.decode(readMedia(f.path));
        const same =
          d.pixels.length === ref.pixels.length &&
          Buffer.compare(Buffer.from(d.pixels.buffer), Buffer.from(ref.pixels.buffer)) === 0;
        expect(same, `${f.path} vs ${group[0].path}`).toBe(true);
      }
    }
  });

  test('tiled RGB matches the scanline chart; alpha present', () => {
    const ref = dec.decode(readMedia('chart_none.exr'));
    const t = dec.decode(readMedia('tiled_zip_64.exr'));
    let diff = 0;
    for (let i = 0; i < ref.pixels.length; i += 4)
      for (let c = 0; c < 3; c++) if (ref.pixels[i + c] !== t.pixels[i + c]) diff++;
    expect(diff).toBe(0);
    // chart has no alpha -> filled with 1.0
    expect(halfToFloat(ref.pixels[3])).toBe(1);
    expect(halfToFloat(t.pixels[(t.width - 1) * 4 + 3])).toBe(1); // alpha ramp reaches 1 at the right edge
    expect(halfToFloat(t.pixels[3])).toBe(0);
  });

  test('explicit channel mapping and missing channels', () => {
    const bytes = readMedia('multilayer.exr');
    const d = dec.decode(bytes, { channels: ['diffuse.R', null, 'Z', null] });
    expect(d.mapping).toEqual(['diffuse.R', null, 'Z', null]);
    const x = 480,
      y = 270;
    const ref = dec.decode(bytes, { layer: 'diffuse' });
    const z = dec.decode(bytes, { layer: 'Z', format: 'float' });
    const p = pixel(d, x, y);
    expect(p[0]).toBe(pixel(ref, x, y)[0]);
    expect(p[1]).toBe(0);
    expect(p[2]).toBeCloseTo(pixel(z, x, y)[0], 1);
    expect(p[3]).toBe(1);
    expect(() => dec.decode(bytes, { layer: 'nope' })).toThrow(/layer 'nope' not found/);
    expect(() => dec.decode(bytes, { channels: ['nope', null, null, null] })).toThrow(ExrError);
  });

  test('deep data is detected and reported as unsupported', () => {
    const bytes = readMedia('deep.exr');
    const info = dec.readInfo(bytes);
    expect(info.parts[0].type).toBe('deep');
    expect(info.parts[0].supported).toBe(false);
    expect(() => dec.decode(bytes)).toThrow(ExrUnsupportedError);
  });

  test('corrupt and truncated input', () => {
    expect(() => dec.readInfo(new Uint8Array(100).fill(7))).toThrow(ExrError);
    expect(() => dec.decode(new Uint8Array(3))).toThrow(ExrError);
    const full = readMedia('chart_zips.exr');
    const truncated = full.slice(0, Math.floor(full.length * 0.6));
    let d: DecodedExr | null = null;
    try {
      d = dec.decode(truncated);
    } catch (e) {
      expect(e).toBeInstanceOf(ExrError);
    }
    if (d) expect(d.failedChunks).toBeGreaterThan(0);
    // the decoder is still usable afterwards
    expect(dec.decode(readMedia('chart_zip.exr')).failedChunks).toBe(0);
  });

  describe.skipIf(!manifest.sequence)('sequence', () => {
    test('48 frames, frame numbers and moving element', () => {
      const seq = manifest.sequence!;
      expect(seq.frames.length).toBe(48);
      expect(seq.frames[0].frame).toBe(1001);
      expect(seq.frames.at(-1)!.frame).toBe(1048);
      let prev: Uint16Array | null = null;
      for (const fr of seq.frames) {
        const bytes = readMedia(fr.path);
        const d = dec.decode(bytes);
        expect(d.info.attributes.comments).toBe(`frame ${fr.frame}`);
        expect(d.info.attributes.framesPerSecond).toEqual([24, 1]);
        checkSamples(d, fr.samples, 0, 0, fr.path);
        if (prev)
          expect(Buffer.compare(Buffer.from(prev.buffer), Buffer.from(d.pixels.buffer))).not.toBe(
            0,
          );
        prev = d.pixels as Uint16Array;
      }
    });
  });
});

describe('layer grouping', () => {
  test('rules', () => {
    const l = groupLayers([
      'A',
      'B',
      'G',
      'R',
      'Z',
      'diffuse.R',
      'diffuse.G',
      'diffuse.B',
      'N.X',
      'N.Y',
      'N.Z',
      'uv.U',
      'uv.V',
      'depth.Z',
      'c.red',
      'c.green',
      'c.blue',
      'c.alpha',
      'lum.Y',
      'lum.A',
      'misc.foo',
      'misc.bar',
    ]);
    const m = Object.fromEntries(l.map((x) => [x.name, x.mapping]));
    expect(l[0].name).toBe('');
    expect(m['']).toEqual(['R', 'G', 'B', 'A']);
    expect(m.Z).toEqual(['Z', 'Z', 'Z', null]);
    expect(m.diffuse).toEqual(['diffuse.R', 'diffuse.G', 'diffuse.B', null]);
    expect(m.N).toEqual(['N.X', 'N.Y', 'N.Z', null]);
    expect(m.uv).toEqual(['uv.U', 'uv.V', null, null]);
    expect(m.depth).toEqual(['depth.Z', 'depth.Z', 'depth.Z', null]);
    expect(m.c).toEqual(['c.red', 'c.green', 'c.blue', 'c.alpha']);
    expect(m.lum).toEqual(['lum.Y', 'lum.Y', 'lum.Y', 'lum.A']);
    expect(m.misc).toEqual(['misc.foo', 'misc.bar', null, null]);
  });
  test('luminance / chroma default layer', () => {
    const l = groupLayers(['BY', 'RY', 'Y']);
    expect(l[0]).toMatchObject({ name: '', mapping: ['Y', 'Y', 'Y', null], kind: 'luminance' });
    expect(l.map((x) => x.name)).toEqual(['', 'BY', 'RY']);
  });
  test('lower-case rgba', () => {
    expect(groupLayers(['r', 'g', 'b', 'a'])[0].mapping).toEqual(['r', 'g', 'b', 'a']);
  });
});
